import Component from "flarum/common/Component";
/** Caixa de console monoespaçada para o tail do log de um passo. */
export default class LiveConsole extends Component {
  view() {
    const text = (this.attrs.text || "").trim();
    return m("pre", {
      className: "MmConsole",
      onupdate: vnode => this.maybeScroll(vnode),
      oncreate: vnode => this.maybeScroll(vnode)
    }, text || "—");
  }
  maybeScroll(vnode) {
    if (this.attrs.follow === false) return;
    const el = vnode.dom;
    el.scrollTop = el.scrollHeight;
  }
}
flarum.reg.add('ramon-mybb-migrator', 'admin/components/LiveConsole', LiveConsole);